// What the platform bindings do beyond haptics, as observable values.
import { PLATFORM } from "lucent:platform";
import { UIDevice } from "lucent:ios/UIKit";
import { Build_VERSION, Looper, VibrationEffect } from "lucent:android/android.os";
import { available } from "lucent:android";
import { main } from "lucent:thread";
import { errorCode as codeOf } from "@lucent-lang/core";

/** The OS name from the SDK (UIDevice.systemName; "Android" + Build.VERSION.RELEASE). */
export async function systemName(): Promise<string> {
  if (PLATFORM === "ios") {
    return main(() => UIDevice.current.systemName);
  } else {
    return `Android ${Build_VERSION.RELEASE ?? "?"}`;
  }
}

/** Identity of platform objects, off and on the main thread. */
export async function identity(): Promise<string> {
  if (PLATFORM === "ios") {
    return main(() => `${UIDevice.current === UIDevice.current}`);
  } else {
    // Async functions run on the Lucent thread, which has no Looper.
    const here = Looper.myLooper() === Looper.getMainLooper();
    const onMain = await main(() => Looper.myLooper() === Looper.getMainLooper());
    return `${here}|${onMain}`;
  }
}

/** A platform error, as the Lucent error code it becomes. */
export async function errorCode(): Promise<string> {
  if (PLATFORM === "ios") {
    // No iOS API in the spike's schemas reports errors yet.
    return "none";
  } else {
    if (!available("android", 26)) return "no VibrationEffect";
    try {
      VibrationEffect.createOneShot(-5, 10);
      return "no error";
    } catch (e) {
      return codeOf(e as Error) ?? "no code";
    }
  }
}
